  "thunder-many": "// 万雷 / 三波の稲妻が上空から異なる近接地点へ順に降り、各着弾点で閃光が弾ける。\nvarying vec2 vUv;\nuniform float uTime,uProgress,uSize,uGlow,uSeed,uAspect,uDuration;\nuniform vec2 uResolution;\nuniform vec3 uColor,uCore;\n// @param uNoise 1 0 3 0.05\n// @param uDensity 1 0.1 3 0.05\n// @param uInner 1 0 3 0.05\n// @param uOuter 1 0 3 0.05\nuniform float uNoise;\nuniform float uDensity;\nuniform float uInner;\nuniform float uOuter;\nfloat sat(float x){return clamp(x,0.,1.);}\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7))+uSeed*.013)*43758.5453);}\nfloat noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}\nfloat fb(vec2 p){return .57*noise(p)+.28*noise(p*2.03)+.15*noise(p*4.13);}\nfloat fade(float q){return 1.-smoothstep(.58,1.,q);}\nfloat pulse(float t){return .20+.80*pow(1.-fract(t),2.);}\nfloat glowline(float d,float w){w=max(w,.002);return uInner*exp(-d/w)+uGlow*uOuter*.65*exp(-d/(w*4.));}\nfloat segment(vec2 p,vec2 a,vec2 b){vec2 v=b-a;float h=sat(dot(p-a,v)/max(dot(v,v),.00001));return length(p-a-v*h);}\nfloat bolt(vec2 p,vec2 a,vec2 b,float seed,float w){vec2 v=b-a;float len=length(v);if(len<.001)return 0.;vec2 ax=v/len,ay=vec2(-ax.y,ax.x);vec2 d=p-a;float x=dot(d,ax)/len,y=dot(d,ay);float q=sat(x);float bend=(noise(vec2(q*9.*uDensity+seed*17.,floor(uTime*18.)))-.5)*.27*len*sin(q*3.14159)*uNoise;float ds=length(vec2((x-q)*len,y-bend));return glowline(ds,w)*(1.-smoothstep(.0,.14,abs(x-q)));}\nfloat orb(vec2 p,vec2 a,float r){float d=length(p-a)/max(.002,r);return exp(-d*d*4.)*uInner+uGlow*uOuter*.6*exp(-d*d);}\nfloat ellipse(vec2 p,vec2 a,vec2 r,float w){vec2 rr=max(r,vec2(.015));return glowline(abs(length((p-a)/rr)-1.)*min(rr.x,rr.y),w);}\nfloat burst(vec2 p,vec2 a,float r,float n,float seed){float z=0.;for(int i=0;i<20;i++){float k=float(i);if(k>=n)break;float theta=k*6.28318/n+.24*hash(vec2(k,seed));vec2 d=vec2(cos(theta),sin(theta));float v=r*(.45+.55*hash(vec2(k,seed+1.)));z+=glowline(segment(p,a+d*v*.55,a+d*v),.007)+orb(p,a+d*v,.019)*.6;}return z;}\nfloat strike(vec2 p,float x,float top,float ground,float q,float w,float seed){float f=sat(q*6.);vec2 a=vec2(x+.06,top),b=vec2(x,mix(top,ground,f));float z=bolt(p,a,b,seed,w);z+=bolt(p,mix(a,b,.4),mix(a,b,.65)+vec2(.16*f,.08),seed+8.,w*.35)*f;float hit=smoothstep(.76,1.,f);z+=hit*(orb(p,vec2(x,ground),.11)*(1.-q)+ellipse(p,vec2(x,ground),vec2(.05+q*.42,.022+q*.10),.008));return z;}\nfloat route(vec2 p,vec2 a,vec2 b,float f,float g,float k){float v=sat(f),w=sat(g);return glowline(segment(p,a,mix(a,b,v)),.005)*v*.6+bolt(p,a,mix(a,b,w),k,.017)*w;}\nfloat rain(vec2 p,float t,float slant){float z=0.;for(int i=0;i<20;i++){float k=float(i),x=(hash(vec2(k,71.))-.5)*1.65;float y=.63-fract(hash(vec2(k,23.))+t*1.6)*1.42;vec2 a=vec2(x+y*slant*.25,y);z+=glowline(segment(p,a,a+vec2(-.025*slant,-.09)),.004)*.22;}return z;}\nvec4 tint(float z,vec3 color){return vec4(mix(color,uCore,smoothstep(.60,1.5,z)),sat(z));}\nvec4 light(float z){return tint(z,uColor);}\nvec4 over(vec4 a,vec4 b){float alpha=b.a+a.a*(1.-b.a);return vec4((b.rgb*b.a+a.rgb*a.a*(1.-b.a))/max(alpha,.0001),alpha);}\nvec4 cloud(vec2 p,vec2 a,vec2 r,float t){vec2 v=(p-a)/max(r,vec2(.02));float d=length(v)+(.5-fb(v*3.+vec2(t*.6,0.)))*.52*uNoise;float alpha=(1.-smoothstep(.66,1.17,d))*.85;float n=fb(v*3.+vec2(t*.7,2.));return vec4(mix(vec3(.075,.095,.15),vec3(.30,.34,.45),n),alpha);}\n\nvec4 effect(vec2 p,float t,float q){float k=min(2.,floor(q*3.)),v=fract(q*3.),x=k<.5?-.43:k<1.5?.43:0.;float z=strike(p,x,.88,-.61,v,.028,k)+burst(p,vec2(x,-.61),.08+.25*v,8.,k)*step(.2,v);return light(z*(1.-v*.75));}\nvoid main(){vec2 p=(vUv-.5)*2.;p*=vec2(max(1.,uAspect),max(1.,1./uAspect));p/=max(.1,uSize);gl_FragColor=effect(p,uTime,uProgress);}",
  "thunder-supercell": "// 巨大積乱雲 / 大きな積乱雲と回転する雲の帯を形成。内部放電と複数地点への落雷が繰り返される。\nvarying vec2 vUv;\nuniform float uTime,uProgress,uSize,uGlow,uSeed,uAspect,uDuration;\nuniform vec2 uResolution;\nuniform vec3 uColor,uCore;\n// @param uNoise 1 0 3 0.05\n// @param uDensity 1 0.1 3 0.05\n// @param uInner 1 0 3 0.05\n// @param uOuter 1 0 3 0.05\nuniform float uNoise;\nuniform float uDensity;\nuniform float uInner;\nuniform float uOuter;\nfloat sat(float x){return clamp(x,0.,1.);}\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7))+uSeed*.013)*43758.5453);}\nfloat noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}\nfloat fb(vec2 p){return .57*noise(p)+.28*noise(p*2.03)+.15*noise(p*4.13);}\nfloat fade(float q){return 1.-smoothstep(.58,1.,q);}\nfloat pulse(float t){return .20+.80*pow(1.-fract(t),2.);}\nfloat glowline(float d,float w){w=max(w,.002);return uInner*exp(-d/w)+uGlow*uOuter*.65*exp(-d/(w*4.));}\nfloat segment(vec2 p,vec2 a,vec2 b){vec2 v=b-a;float h=sat(dot(p-a,v)/max(dot(v,v),.00001));return length(p-a-v*h);}\nfloat bolt(vec2 p,vec2 a,vec2 b,float seed,float w){vec2 v=b-a;float len=length(v);if(len<.001)return 0.;vec2 ax=v/len,ay=vec2(-ax.y,ax.x);vec2 d=p-a;float x=dot(d,ax)/len,y=dot(d,ay);float q=sat(x);float bend=(noise(vec2(q*9.*uDensity+seed*17.,floor(uTime*18.)))-.5)*.27*len*sin(q*3.14159)*uNoise;float ds=length(vec2((x-q)*len,y-bend));return glowline(ds,w)*(1.-smoothstep(.0,.14,abs(x-q)));}\nfloat orb(vec2 p,vec2 a,float r){float d=length(p-a)/max(.002,r);return exp(-d*d*4.)*uInner+uGlow*uOuter*.6*exp(-d*d);}\nfloat ellipse(vec2 p,vec2 a,vec2 r,float w){vec2 rr=max(r,vec2(.015));return glowline(abs(length((p-a)/rr)-1.)*min(rr.x,rr.y),w);}\nfloat burst(vec2 p,vec2 a,float r,float n,float seed){float z=0.;for(int i=0;i<20;i++){float k=float(i);if(k>=n)break;float theta=k*6.28318/n+.24*hash(vec2(k,seed));vec2 d=vec2(cos(theta),sin(theta));float v=r*(.45+.55*hash(vec2(k,seed+1.)));z+=glowline(segment(p,a+d*v*.55,a+d*v),.007)+orb(p,a+d*v,.019)*.6;}return z;}\nfloat strike(vec2 p,float x,float top,float ground,float q,float w,float seed){float f=sat(q*6.);vec2 a=vec2(x+.06,top),b=vec2(x,mix(top,ground,f));float z=bolt(p,a,b,seed,w);z+=bolt(p,mix(a,b,.4),mix(a,b,.65)+vec2(.16*f,.08),seed+8.,w*.35)*f;float hit=smoothstep(.76,1.,f);z+=hit*(orb(p,vec2(x,ground),.11)*(1.-q)+ellipse(p,vec2(x,ground),vec2(.05+q*.42,.022+q*.10),.008));return z;}\nfloat route(vec2 p,vec2 a,vec2 b,float f,float g,float k){float v=sat(f),w=sat(g);return glowline(segment(p,a,mix(a,b,v)),.005)*v*.6+bolt(p,a,mix(a,b,w),k,.017)*w;}\nfloat rain(vec2 p,float t,float slant){float z=0.;for(int i=0;i<20;i++){float k=float(i),x=(hash(vec2(k,71.))-.5)*1.65;float y=.63-fract(hash(vec2(k,23.))+t*1.6)*1.42;vec2 a=vec2(x+y*slant*.25,y);z+=glowline(segment(p,a,a+vec2(-.025*slant,-.09)),.004)*.22;}return z;}\nvec4 tint(float z,vec3 color){return vec4(mix(color,uCore,smoothstep(.60,1.5,z)),sat(z));}\nvec4 light(float z){return tint(z,uColor);}\nvec4 over(vec4 a,vec4 b){float alpha=b.a+a.a*(1.-b.a);return vec4((b.rgb*b.a+a.rgb*a.a*(1.-b.a))/max(alpha,.0001),alpha);}\nvec4 cloud(vec2 p,vec2 a,vec2 r,float t){vec2 v=(p-a)/max(r,vec2(.02));float d=length(v)+(.5-fb(v*3.+vec2(t*.6,0.)))*.52*uNoise;float alpha=(1.-smoothstep(.66,1.17,d))*.85;float n=fb(v*3.+vec2(t*.7,2.));return vec4(mix(vec3(.075,.095,.15),vec3(.30,.34,.45),n),alpha);}\n\nvec4 effect(vec2 p,float t,float q){vec4 c=cloud(p,vec2(0.,.61),vec2(.88,.26),t);c=over(c,cloud(p,vec2(.06,.30),vec2(.66,.23),t+4.));vec2 v=(p-vec2(0.,.42))/vec2(1.,.32);float r=length(v),a=atan(v.y,v.x);float swirl=pow(.5+.5*sin(a*3.-r*14.+t*6.),3.)*(1.-smoothstep(.5,.85,r))*smoothstep(.05,.14,r);c=over(c,vec4(.32,.38,.52,swirl*.46));float k=floor(t*6.),z=orb(p,vec2(.45*sin(t*9.),.5),.17)*pulse(t*6.);for(int i=0;i<2;i++){float x=(hash(vec2(k,float(i)))-.5)*1.42;z+=strike(p,x,.25,-.73,fract(t*6.+float(i)*.43),.019,k+float(i))*pulse(t*6.+float(i)*.43);}return over(c,light(z));}\nvoid main(){vec2 p=(vUv-.5)*2.;p*=vec2(max(1.,uAspect),max(1.,1./uAspect));p/=max(.1,uSize);gl_FragColor=effect(p,uTime,uProgress);}"
